9	const CHUNK_VS = `#version 300 es
10	precision highp float;
11	layout(location=0) in vec3 aPos;
12	layout(location=1) in vec2 aUv;
13	layout(location=2) in float aLayer;
14	layout(location=3) in float aAnim;
15	layout(location=4) in vec2 aLight;
16	layout(location=5) in float aAo;
17	layout(location=6) in vec3 aTint;
18	layout(location=7) in float aShade;
19	layout(location=8) in vec3 aNormal;
20	uniform mat4 uViewProj;
21	uniform int uAnimFrames[8];
22	out vec2 vUv;
23	out vec2 vLight;
24	out float vAo;
25	out vec3 vTint;
26	out float vShade;
27	out vec3 vWorld;
28	out vec3 vNormal;
29	flat out int vLayer;
30	void main() {
31	  gl_Position = uViewProj * vec4(aPos, 1.0);
32	  vUv = aUv;
33	  vLight = aLight;
34	  vAo = aAo;
35	  vTint = aTint;
36	  vShade = aShade;
37	  vWorld = aPos;
38	  vNormal = aNormal;
39	  int layer = int(aLayer + 0.5);
40	  if (aAnim >= 0.0) layer = uAnimFrames[int(aAnim + 0.5)];
41	  vLayer = layer;
42	}`;
