146	const SKY_VS = `#version 300 es
147	precision highp float;
148	out vec2 vNdc;
149	void main() {
150	  vec2 pos[3] = vec2[3](vec2(-1.0, -1.0), vec2(3.0, -1.0), vec2(-1.0, 3.0));
151	  vNdc = pos[gl_VertexID];
152	  gl_Position = vec4(pos[gl_VertexID], 0.0, 1.0);
153	}`;
