155	const SKY_FS = `#version 300 es
156	precision highp float;
157	uniform mat4 uInvViewProj;
158	uniform vec3 uCam;
159	uniform vec3 uSkyTop;
160	uniform vec3 uSkyHorizon;
161	uniform vec3 uSunDir;
162	uniform vec3 uSunGlow;
163	uniform float uStarAlpha;
164	in vec2 vNdc;
165	out vec4 outColor;
166	
167	float hash21(vec2 p) {
168	  p = fract(p * vec2(123.34, 456.21));
169	  p += dot(p, p + 45.32);
170	  return fract(p.x * p.y);
171	}
172	void main() {
173	  vec4 p = uInvViewProj * vec4(vNdc, 1.0, 1.0);
174	  vec3 dir = normalize(p.xyz / p.w - uCam);
175	  float up = clamp(dir.y, 0.0, 1.0);
176	  vec3 c = mix(uSkyHorizon, uSkyTop, pow(up, 0.55));
177	  if (dir.y < 0.0) c = uSkyHorizon;
178	  float sun = max(dot(dir, normalize(uSunDir)), 0.0);
179	  c += uSunGlow * pow(sun, 320.0);
180	  if (uStarAlpha > 0.01 && dir.y > 0.02) {
181	    vec2 sph = vec2(atan(dir.z, dir.x), asin(clamp(dir.y, -1.0, 1.0)));
182	    vec2 grid = sph * vec2(90.0, 45.0);
183	    vec2 id = floor(grid);
184	    vec2 f = fract(grid);
185	    float h = hash21(id);
186	    float star = step(0.986, h) * smoothstep(0.18, 0.0, length(f - 0.5));
187	    c += vec3(0.9, 0.95, 1.0) * star * uStarAlpha;
188	  }
189	  outColor = vec4(c, 1.0);
190	}`;
