466	  private createShadowMap(): void {
467	    const gl = this.gl;
468	    try {
469	      const tex = gl.createTexture()!;
470	      gl.bindTexture(gl.TEXTURE_2D, tex);
471	      gl.texImage2D(gl.TEXTURE_2D, 0, gl.DEPTH_COMPONENT24, this.shadowSize, this.shadowSize, 0,
472	        gl.DEPTH_COMPONENT, gl.UNSIGNED_INT, null);
473	      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
474	      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
475	      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
476	      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
477	      const fbo = gl.createFramebuffer()!;
478	      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
479	      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.TEXTURE_2D, tex, 0);
480	      gl.drawBuffers([gl.NONE]);
481	      const status = gl.checkFramebufferStatus(gl.FRAMEBUFFER);
482	      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
483	      if (status !== gl.FRAMEBUFFER_COMPLETE) {
484	        console.warn('shadow framebuffer incomplete', status);
485	        gl.deleteTexture(tex);
486	        gl.deleteFramebuffer(fbo);
487	        return;
488	      }
489	      this.shadowTex = tex;
490	      this.shadowFbo = fbo;
491	      this.shadowReady = true;
492	    } catch (err) {
493	      console.warn('shadow mapping unavailable', err);
494	      this.shadowReady = false;
495	    }
496	  }
