498	  setShadowQuality(enabled: boolean, size = 2048): void {
499	    this.shadowEnabled = enabled;
500	    const next = Math.max(512, Math.min(4096, size));
501	    if (next === this.shadowSize && this.shadowReady) return;
502	    this.shadowSize = next;
503	    if (this.shadowFbo) this.gl.deleteFramebuffer(this.shadowFbo);
504	    if (this.shadowTex) this.gl.deleteTexture(this.shadowTex);
505	    this.shadowFbo = null;
506	    this.shadowTex = null;
507	    this.shadowReady = false;
508	    if (enabled) this.createShadowMap();
509	  }
