511	  private updateFrustum(): void {
512	    const m = this.vp;
513	    const f = this.frustum;
514	    f[0] = m[0] + m[3]; f[1] = m[4] + m[7]; f[2] = m[8] + m[11]; f[3] = m[12] + m[15];
515	    f[4] = m[3] - m[0]; f[5] = m[7] - m[4]; f[6] = m[11] - m[8]; f[7] = m[15] - m[12];
516	    f[8] = m[1] + m[3]; f[9] = m[5] + m[7]; f[10] = m[9] + m[11]; f[11] = m[13] + m[15];
517	    f[12] = m[3] - m[1]; f[13] = m[7] - m[5]; f[14] = m[11] - m[9]; f[15] = m[15] - m[13];
518	    f[16] = m[2] + m[3]; f[17] = m[6] + m[7]; f[18] = m[10] + m[11]; f[19] = m[14] + m[15];
519	    f[20] = m[3] - m[2]; f[21] = m[7] - m[6]; f[22] = m[11] - m[10]; f[23] = m[15] - m[14];
520	  }
