522	  private chunkVisible(x: number, z: number): boolean {
523	    const f = this.frustum;
524	    const y0 = -64, y1 = 180;
525	    for (let p = 0; p < 24; p += 4) {
526	      const a = f[p], b = f[p + 1], c = f[p + 2], d = f[p + 3];
527	      const px = a >= 0 ? x + 16 : x;
528	      const py = b >= 0 ? y1 : y0;
529	      const pz = c >= 0 ? z + 16 : z;
530	      if (a * px + b * py + c * pz + d < 0) return false;
531	    }
532	    return true;
533	  }
