535	  private renderShadowMap(world: World, sunDir: number[], day: number, elapsed: number): void {
536	    const gl = this.gl;
537	    const strength = this.shadowEnabled && this.shadowReady ? smoothstep(0.04, 0.22, sunDir[1]) * 0.9 : 0;
538	    this.shadowStrength = strength;
539	    if (strength <= 0.01 || !this.shadowFbo || !this.shadowTex) return;
540	    const centerX = this.eye[0], centerZ = this.eye[2];
541	    const radius = 86;
542	    const light = [centerX + sunDir[0] * 170, this.eye[1] + sunDir[1] * 170, centerZ + sunDir[2] * 170];
543	    const up = Math.abs(sunDir[1]) > 0.96 ? [0, 0, 1] : [0, 1, 0];
544	    const lightView = mat4();
545	    lookAt(lightView, light[0], light[1], light[2], centerX, this.eye[1], centerZ, up[0], up[1], up[2]);
546	    const lightProj = ortho(mat4(), -radius, radius, -radius, radius, 1, 380);
547	    multiply(this.shadowVP, lightProj, lightView);
548	
549	    gl.bindFramebuffer(gl.FRAMEBUFFER, this.shadowFbo);
550	    gl.viewport(0, 0, this.shadowSize, this.shadowSize);
551	    gl.depthMask(true);
552	    gl.enable(gl.DEPTH_TEST);
553	    gl.disable(gl.BLEND);
554	    gl.enable(gl.CULL_FACE);
555	    gl.cullFace(gl.BACK);
556	    gl.enable(gl.POLYGON_OFFSET_FILL);
557	    gl.polygonOffset(1.2, 2.5);
558	    gl.clear(gl.DEPTH_BUFFER_BIT);
559	
560	    this.shadowProgram.use();
561	    this.shadowProgram.mat4('uLightVP', this.shadowVP);
562	    this.updateAnimFrames(elapsed);
563	    this.shadowProgram.intArray('uAnimFrames', this.animFrames);
564	    this.shadowProgram.f('uAlphaCutoff', 0.3);
565	    gl.activeTexture(gl.TEXTURE0);
566	    gl.bindTexture(gl.TEXTURE_2D_ARRAY, this.assets.texArray);
567	    this.shadowProgram.i('uTex', 0);
568	    const r2 = (radius + 24) * (radius + 24);
569	    for (const c of world.chunks.values()) {
570	      const dx = c.cx * 16 + 8 - centerX, dz = c.cz * 16 + 8 - centerZ;
571	      if (dx * dx + dz * dz > r2) continue;
572	      const mesh = this.meshes.get(`${c.cx},${c.cz}`);
573	      if (!mesh?.solid) continue;
574	      gl.bindVertexArray(mesh.solid.vao);
575	      gl.drawElements(gl.TRIANGLES, mesh.solid.count, gl.UNSIGNED_INT, 0);
576	    }
577	    gl.bindVertexArray(null);
578	    gl.disable(gl.POLYGON_OFFSET_FILL);
579	    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
580	    gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
581	    gl.cullFace(gl.BACK);
582	  }
