584	  private imageTexture(img: ImageBitmap, filter: number): WebGLTexture {
585	    const gl = this.gl;
586	    const t = gl.createTexture()!;
587	    gl.bindTexture(gl.TEXTURE_2D, t);
588	    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
589	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST_MIPMAP_LINEAR);
590	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
591	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT);
592	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.REPEAT);
593	    gl.generateMipmap(gl.TEXTURE_2D);
594	    return t;
595	  }
