597	  async buildAll(world: World, progress: (f: number, label: string) => void): Promise<void> {
598	    const chunks = [...world.chunks.values()].sort((a, b) => (a.cx * a.cx + a.cz * a.cz) - (b.cx * b.cx + b.cz * b.cz));
599	    const total = chunks.length;
600	    let done = 0;
601	    for (const c of chunks) {
602	      this.buildChunk(world, c.cx, c.cz);
603	      done++;
604	      if (done % 4 === 0 || done === total) {
605	        progress(0.93 + 0.07 * (done / total), `Building meshes ${done}/${total}`);
606	        await new Promise(r => setTimeout(r, 0));
607	      }
608	    }
609	  }
