646	  render(world: World, eyeX: number, eyeY: number, eyeZ: number, yaw: number, pitch: number,
647	    target: RenderTarget | null, worldTicks: number, elapsed: number, renderDistance: number): void {
648	    const gl = this.gl;
649	    this.eye = [eyeX, eyeY, eyeZ];
650	    this.yaw = yaw;
651	    this.pitch = pitch;
652	    this.frameTime = elapsed;
653	    const aspect = gl.drawingBufferWidth / Math.max(1, gl.drawingBufferHeight);
654	    perspective(this.proj, (this.fov * Math.PI) / 180, aspect, 0.05, 512);
655	    viewFromYawPitch(this.view, yaw, pitch, eyeX, eyeY, eyeZ);
656	    multiply(this.vp, this.proj, this.view);
657	    invert(this.invVp, this.vp);
658	    this.updateFrustum();
659	
660	    const time = ((worldTicks % 24000) + 24000) % 24000;
661	    const angle = (time / 24000) * Math.PI * 2;
662	    const sunDir: [number, number, number] = [Math.cos(angle), Math.sin(angle), 0.18];
663	    const sl = Math.hypot(...sunDir);
664	    sunDir[0] /= sl; sunDir[1] /= sl; sunDir[2] /= sl;
665	    const day = smoothstep(-0.16, 0.16, sunDir[1]);
666	    const skyTop = hexToRgb('#78a7ff').map(v => v * day) as [number, number, number];
667	    const fogDay = hexToRgb('#c0d8ff');
668	    const fogNight = hexToRgb('#0c0c16');
669	    const horizon: [number, number, number] = [
670	      fogNight[0] + (fogDay[0] - fogNight[0]) * day,
671	      fogNight[1] + (fogDay[1] - fogNight[1]) * day,
672	      fogNight[2] + (fogDay[2] - fogNight[2]) * day,
673	    ];
674	    const sunset = Math.exp(-Math.pow(sunDir[1] / 0.22, 2)) * (0.35 + 0.65 * (1 - day));
675	    const sunsetCol = hexToRgb('#da6333');
676	    for (let i = 0; i < 3; i++) horizon[i] = horizon[i] * (1 - sunset * 0.25) + sunsetCol[i] * sunset * 0.5;
677	
678	    this.renderShadowMap(world, sunDir, day, elapsed);
679	
680	    const eyeBlock = world.getBlock(Math.floor(eyeX), Math.floor(eyeY), Math.floor(eyeZ));
681	    const underwater = eyeBlock !== 0 && this.rocks.byName.get('water')?.id === eyeBlock;
682	    let fogColor: [number, number, number] = horizon;
683	    let fogStart = renderDistance * 16 * 0.88;
684	    let fogEnd = renderDistance * 16;
685	    if (underwater) {
686	      fogColor = hexToRgb('#050533');
687	      fogStart = 0;
688	      fogEnd = Math.min(96, renderDistance * 16);
689	    }
690	
691	    let sunScreen: [number, number] = [0.5, 0.5];
692	    let sunVisibility = 0;
693	    if (!underwater && sunDir[1] > -0.02) {
694	      const sx = eyeX + sunDir[0] * 400, sy = eyeY + sunDir[1] * 400, sz = eyeZ + sunDir[2] * 400;
695	      const cx = this.vp[0] * sx + this.vp[4] * sy + this.vp[8] * sz + this.vp[12];
696	      const cy = this.vp[1] * sx + this.vp[5] * sy + this.vp[9] * sz + this.vp[13];
697	      const cw = this.vp[3] * sx + this.vp[7] * sy + this.vp[11] * sz + this.vp[15];
698	      if (cw > 0.0001) {
699	        const nx = cx / cw, ny = cy / cw;
700	        const edge = Math.max(Math.abs(nx), Math.abs(ny));
701	        if (edge < 1.35) {
702	          sunScreen = [nx * 0.5 + 0.5, ny * 0.5 + 0.5];
703	          sunVisibility = smoothstep(-0.04, 0.08, sunDir[1]) * (1 - smoothstep(1.0, 1.35, edge));
704	        }
705	      }
706	    }
707	
708	    if (this.usePost) {
709	      this.postfx.resize(gl.drawingBufferWidth, gl.drawingBufferHeight);
710	      this.postfx.begin();
711	    } else {
712	      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
713	      gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
714	    }
715	    gl.clearColor(fogColor[0], fogColor[1], fogColor[2], 1);
716	    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
717	    gl.enable(gl.DEPTH_TEST);
718	    gl.depthFunc(gl.LEQUAL);
719	
720	    if (!underwater) {
721	      gl.disable(gl.DEPTH_TEST);
722	      gl.disable(gl.CULL_FACE);
723	      gl.disable(gl.BLEND);
724	      this.skyProgram.use();
725	      this.skyProgram.mat4('uInvViewProj', this.invVp);
726	      this.skyProgram.v3('uCam', eyeX, eyeY, eyeZ);
727	      this.skyProgram.v3('uSkyTop', skyTop[0], skyTop[1], skyTop[2]);
728	      this.skyProgram.v3('uSkyHorizon', horizon[0], horizon[1], horizon[2]);
729	      this.skyProgram.v3('uSunDir', sunDir[0], sunDir[1], sunDir[2]);
730	      this.skyProgram.v3('uSunGlow', 0.14, 0.10, 0.04);
731	      this.skyProgram.f('uStarAlpha', smoothstep(-0.06, -0.35, sunDir[1]) * 0.8);
732	      gl.bindVertexArray(this.skyVao);
733	      gl.drawArrays(gl.TRIANGLES, 0, 3);
734	      gl.enable(gl.DEPTH_TEST);
735	      this.drawCelestial(worldTicks, sunDir, day);
736	    }
737	
738	    gl.enable(gl.CULL_FACE);
739	    gl.cullFace(gl.BACK);
740	    gl.frontFace(gl.CCW);
741	    gl.enable(gl.DEPTH_TEST);
742	    gl.depthMask(true);
743	    gl.disable(gl.BLEND);
744	    this.chunkProgram.use();
745	    this.chunkProgram.mat4('uViewProj', this.vp);
746	    this.chunkProgram.v3('uCam', eyeX, eyeY, eyeZ);
747	    this.chunkProgram.v3('uFogColor', fogColor[0], fogColor[1], fogColor[2]);
748	    this.chunkProgram.f('uFogStart', fogStart);
749	    this.chunkProgram.f('uFogEnd', fogEnd);
750	    this.chunkProgram.f('uAlphaCutoff', 0.3);
751	    this.chunkProgram.v3('uAmbientColor', 12 / 255, 14 / 255, 19 / 255);
752	    const nightSkyLight = hexToRgb('#7a7aff');
753	    const daySkyLight = [1, 1, 1];
754	    this.chunkProgram.v3('uSkyLightColor',
755	      nightSkyLight[0] + (daySkyLight[0] - nightSkyLight[0]) * day,
756	      nightSkyLight[1] + (daySkyLight[1] - nightSkyLight[1]) * day,
757	      nightSkyLight[2] + (daySkyLight[2] - nightSkyLight[2]) * day);
758	    const blockLight = hexToRgb('#ffd88c');
759	    this.chunkProgram.v3('uBlockLightColor', blockLight[0], blockLight[1], blockLight[2]);
760	    this.chunkProgram.f('uSkyFactor', 0.24 + 0.76 * day);
761	    this.chunkProgram.f('uBlockFactor', 1.4);
762	    this.chunkProgram.f('uGamma', 0.5);
763	    this.chunkProgram.v3('uSunDir', sunDir[0], sunDir[1], sunDir[2]);
764	    this.chunkProgram.v3('uSunColor', 1.0, 0.92, 0.78);
765	    this.chunkProgram.v3('uSkyTopColor', skyTop[0], skyTop[1], skyTop[2]);
766	    this.chunkProgram.v3('uSkyHorizonColor', horizon[0], horizon[1], horizon[2]);
767	    this.chunkProgram.f('uTime', elapsed);
768	    this.chunkProgram.i('uWaterLayer', this.rocks.byName.get('water')?.fluidLayer ?? -1);
769	    this.chunkProgram.i('uDebugMode', this.debugMode);
770	    this.chunkProgram.f('uShadowStrength', this.shadowStrength);
771	    this.chunkProgram.mat4('uLightVP', this.shadowVP);
772	    gl.activeTexture(gl.TEXTURE0);
773	    gl.bindTexture(gl.TEXTURE_2D_ARRAY, this.assets.texArray);
774	    this.chunkProgram.i('uTex', 0);
775	    gl.activeTexture(gl.TEXTURE1);
776	    gl.bindTexture(gl.TEXTURE_2D, this.shadowTex);
777	    this.chunkProgram.i('uShadowMap', 1);
778	    gl.activeTexture(gl.TEXTURE0);
779	    this.updateAnimFrames(elapsed);
780	    this.chunkProgram.intArray('uAnimFrames', this.animFrames);
781	
782	    this.drawStats.chunks = 0;
783	    this.drawStats.translucent = 0;
784	    this.drawStats.triangles = 0;
785	    const maxDist = renderDistance * 16 + 20;
786	    const sorted: { mesh: ChunkMesh, dist: number }[] = [];
787	    for (const c of world.chunks.values()) {
788	      const cxw = c.cx * 16 + 8, czw = c.cz * 16 + 8;
789	      const dx = cxw - eyeX, dz = czw - eyeZ;
790	      const dist = Math.hypot(dx, dz);
791	      if (dist > maxDist) continue;
792	      if (!this.chunkVisible(c.cx * 16, c.cz * 16)) continue;
793	      const mesh = this.meshes.get(`${c.cx},${c.cz}`);
794	      if (!mesh) continue;
795	      if (mesh.solid) {
796	        gl.bindVertexArray(mesh.solid.vao);
797	        gl.drawElements(gl.TRIANGLES, mesh.solid.count, gl.UNSIGNED_INT, 0);
798	        this.drawStats.chunks++;
799	        this.drawStats.triangles += mesh.solid.count / 3;
800	      }
801	      if (mesh.translucent) sorted.push({ mesh, dist });
802	    }
803	
804	    if (this.extraWorldRenderer) {
805	      this.extraWorldRenderer(gl, this.vp, [eyeX, eyeY, eyeZ], elapsed, day);
806	      this.chunkProgram.use();
807	      gl.activeTexture(gl.TEXTURE0);
808	      gl.bindTexture(gl.TEXTURE_2D_ARRAY, this.assets.texArray);
809	      this.chunkProgram.i('uTex', 0);
810	      gl.enable(gl.DEPTH_TEST);
811	      gl.depthMask(true);
812	      gl.enable(gl.CULL_FACE);
813	      gl.cullFace(gl.BACK);
814	      gl.disable(gl.BLEND);
815	    }
816	
817	    if (sorted.length) {
818	      sorted.sort((a, b) => b.dist - a.dist);
819	      gl.enable(gl.BLEND);
820	      gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
821	      gl.depthMask(false);
822	      gl.disable(gl.CULL_FACE);
823	      this.chunkProgram.f('uAlphaCutoff', 0.0);
824	      for (const { mesh } of sorted) {
825	        if (!mesh.translucent) continue;
826	        gl.bindVertexArray(mesh.translucent.vao);
827	        gl.drawElements(gl.TRIANGLES, mesh.translucent.count, gl.UNSIGNED_INT, 0);
828	        this.drawStats.translucent++;
829	        this.drawStats.triangles += mesh.translucent.count / 3;
830	      }
831	      gl.depthMask(true);
832	      gl.enable(gl.CULL_FACE);
833	      this.chunkProgram.f('uAlphaCutoff', 0.3);
834	    }
835	
836	    if (!underwater) this.drawClouds(eyeX, eyeY, eyeZ, day, elapsed);
837	
838	    if (target) {
839	      gl.enable(gl.BLEND);
840	      gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
841	      this.lineProgram.use();
842	      this.lineProgram.mat4('uViewProj', this.vp);
843	      this.lineProgram.v3('uOrigin', target.x, target.y, target.z);
844	      this.lineProgram.v4('uColor', 0, 0, 0, 0.55);
845	      gl.bindVertexArray(this.lineVao);
846	      gl.drawArrays(gl.LINES, 0, 24);
847	      gl.disable(gl.BLEND);
848	    }
849	    this.drawViewmodel(elapsed);
850	    gl.bindVertexArray(null);
851	    if (this.usePost) this.postfx.end({ sunScreen, sunVisibility, underwater, time: elapsed });
852	  }
