889	  private buildHandMesh(): void {
890	    const gl = this.gl;
891	    const data: number[] = [];
892	    const faceShade = VIEW_FACE_LIGHT;
893	    const addBox = (x1: number, y1: number, z1: number, x2: number, y2: number, z2: number, color: number[]) => {
894	      const p = [
895	        [x1, y1, z2], [x1, y1, z1], [x2, y1, z1], [x2, y1, z2],
896	        [x1, y2, z1], [x1, y2, z2], [x2, y2, z2], [x2, y2, z1],
897	      ];
898	      const faces = [
899	        [[0, 3, 2, 1], 0], [[4, 5, 6, 7], 1], [[1, 2, 6, 5], 2],
900	        [[0, 4, 7, 3], 3], [[0, 1, 5, 4], 4], [[3, 7, 6, 2], 5],
901	      ];
902	      for (const [quad, dir] of faces as [number[], number][]) {
903	        const shade = faceShade[dir];
904	        for (const i of [quad[0], quad[1], quad[2], quad[0], quad[2], quad[3]]) {
905	          data.push(p[i][0], p[i][1], p[i][2], color[0] * shade, color[1] * shade, color[2] * shade);
906	        }
907	      }
908	    };
909	    addBox(-0.085, -0.68, -0.075, 0.085, -0.5, 0.075, [0.70, 0.52, 0.40]);
910	    addBox(-0.085, -0.56, -0.075, 0.085, 0.08, 0.075, [0.72, 0.54, 0.42]);
911	    addBox(-0.105, -0.02, -0.095, 0.105, 0.30, 0.095, [0.16, 0.53, 0.58]);
912	    this.handCount = data.length / 6;
913	    gl.bindBuffer(gl.ARRAY_BUFFER, this.handVbo);
914	    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(data), gl.STATIC_DRAW);
915	    gl.bindVertexArray(this.handVao);
916	    gl.bindBuffer(gl.ARRAY_BUFFER, this.handVbo);
917	    gl.enableVertexAttribArray(0);
918	    gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 24, 0);
919	    gl.enableVertexAttribArray(1);
920	    gl.vertexAttribPointer(1, 3, gl.FLOAT, false, 24, 12);
921	    gl.bindVertexArray(null);
922	  }
