924	  private heldTint(mode: number, fixed: [number, number, number], ti: number): [number, number, number] {
925	    if (ti < 0) return [1, 1, 1];
926	    if (mode === 1) return hexToRgb('#91bd59');
927	    if (mode === 2) return hexToRgb('#77ab2f');
928	    if (mode === 3) return hexToRgb('#3f76e4');
929	    if (mode === 4) return fixed;
930	    return [1, 1, 1];
