933	  private rebuildHeldMesh(): void {
934	    const gl = this.gl;
935	    if (this.viewVbo) gl.deleteBuffer(this.viewVbo);
936	    this.viewVbo = null;
937	    this.viewCount = 0;
938	    if (this.heldId <= 0) return;
