1179	  private updateAnimFrames(elapsed: number): void {
1180	    const tick = Math.floor(elapsed * 20);
1181	    for (let i = 0; i < this.animFrames.length; i++) this.animFrames[i] = 0;
1182	    for (const info of this.assets.manifest.animTextures) {
1183	      const frames = info.frames;
1184	      let physical = 0;
1185	      if (info.frameList && info.frameList.length) {
1186	        const entries = info.frameList.map(e => typeof e === 'number' ? { index: e, time: info.frametime } : e);
1187	        let total = 0;
1188	        for (const e of entries) total += Math.max(1, e.time);
1189	        let t = tick % Math.max(1, total);
1190	        for (const e of entries) {
1191	          if (t < e.time) { physical = e.index; break; }
1192	          t -= e.time;
1193	        }
1194	      } else {
1195	        const f = Math.max(1, info.frametime);
1196	        physical = Math.floor(tick / f) % frames;
1197	      }
1198	      this.animFrames[info.id] = info.layer + (physical % frames);
1199	    }
1200	  }
