1	export type Mat4 = Float32Array;
2	
3	export function mat4(): Mat4 { return new Float32Array(16); }
4	
5	export function perspective(out: Mat4, fovy: number, aspect: number, near: number, far: number): Mat4 {
6	  const f = 1 / Math.tan(fovy / 2);
7	  out.fill(0);
8	  out[0] = f / aspect;
9	  out[5] = f;
10	  out[10] = (far + near) / (near - far);
11	  out[11] = -1;
12	  out[14] = (2 * far * near) / (near - far);
13	  return out;
14	}
15	
16	export function multiply(out: Mat4, a: Mat4, b: Mat4): Mat4 {
17	  const a00 = a[0], a01 = a[1], a02 = a[2], a03 = a[3];
18	  const a10 = a[4], a11 = a[5], a12 = a[6], a13 = a[7];
19	  const a20 = a[8], a21 = a[9], a22 = a[10], a23 = a[11];
20	  const a30 = a[12], a31 = a[13], a32 = a[14], a33 = a[15];
21	  for (let i = 0; i < 4; i++) {
22	    const b0 = b[i * 4], b1 = b[i * 4 + 1], b2 = b[i * 4 + 2], b3 = b[i * 4 + 3];
23	    out[i * 4] = b0 * a00 + b1 * a10 + b2 * a20 + b3 * a30;
24	    out[i * 4 + 1] = b0 * a01 + b1 * a11 + b2 * a21 + b3 * a31;
25	    out[i * 4 + 2] = b0 * a02 + b1 * a12 + b2 * a22 + b3 * a32;
26	    out[i * 4 + 3] = b0 * a03 + b1 * a13 + b2 * a23 + b3 * a33;
27	  }
28	  return out;
29	}
30	
31	export function basisFromYawPitch(yaw: number, pitch: number) {
32	  const cp = Math.cos(pitch), sp = Math.sin(pitch);
33	  const sy = Math.sin(yaw), cy = Math.cos(yaw);
34	  const fx = -sy * cp, fy = -sp, fz = cy * cp;
35	  // right = forward x up
36	  let rx = -fz, ry = 0, rz = fx;
37	  const rl = Math.hypot(rx, rz) || 1;
38	  rx /= rl; rz /= rl;
39	  // up = right x forward
40	  const ux = ry * fz - rz * fy;
41	  const uy = rz * fx - rx * fz;
42	  const uz = rx * fy - ry * fx;
43	  return { fx, fy, fz, rx, ry, rz, ux, uy, uz };
44	}
45	
46	export function viewFromYawPitch(out: Mat4, yaw: number, pitch: number, ex: number, ey: number, ez: number): Mat4 {
47	  const { fx, fy, fz, rx, ry, rz, ux, uy, uz } = basisFromYawPitch(yaw, pitch);
48	  const de = rx * ex + ry * ey + rz * ez;
49	  const ue = ux * ex + uy * ey + uz * ez;
50	  const fe = fx * ex + fy * ey + fz * ez;
51	  out[0] = rx; out[1] = ux; out[2] = -fx; out[3] = 0;
52	  out[4] = ry; out[5] = uy; out[6] = -fy; out[7] = 0;
53	  out[8] = rz; out[9] = uz; out[10] = -fz; out[11] = 0;
54	  out[12] = -de; out[13] = -ue; out[14] = fe; out[15] = 1;
55	  return out;
56	}
57	
58	export function identity(out: Mat4): Mat4 {
59	  out.fill(0);
60	  out[0] = 1; out[5] = 1; out[10] = 1; out[15] = 1;
61	  return out;
62	}
63	
64	export function translation(out: Mat4, x: number, y: number, z: number): Mat4 {
65	  identity(out);
66	  out[12] = x; out[13] = y; out[14] = z;
67	  return out;
68	}
69	
70	export function scaling(out: Mat4, x: number, y: number, z: number): Mat4 {
71	  identity(out);
72	  out[0] = x; out[5] = y; out[10] = z;
73	  return out;
74	}
75	
76	export function rotationX(out: Mat4, angle: number): Mat4 {
77	  const c = Math.cos(angle), s = Math.sin(angle);
78	  identity(out);
79	  out[5] = c; out[6] = s; out[9] = -s; out[10] = c;
80	  return out;
81	}
82	
83	export function rotationY(out: Mat4, angle: number): Mat4 {
84	  const c = Math.cos(angle), s = Math.sin(angle);
85	  identity(out);
86	  out[0] = c; out[2] = -s; out[8] = s; out[10] = c;
87	  return out;
88	}
89	
90	export function rotationZ(out: Mat4, angle: number): Mat4 {
91	  const c = Math.cos(angle), s = Math.sin(angle);
92	  identity(out);
93	  out[0] = c; out[1] = s; out[4] = -s; out[5] = c;
94	  return out;
95	}
96	
97	export function lookAt(out: Mat4, ex: number, ey: number, ez: number, tx: number, ty: number, tz: number, ux: number, uy: number, uz: number): Mat4 {
98	  let fx = tx - ex, fy = ty - ey, fz = tz - ez;
99	  let fl = Math.hypot(fx, fy, fz) || 1;
100	  fx /= fl; fy /= fl; fz /= fl;
101	  let sx = fy * uz - fz * uy, sy = fz * ux - fx * uz, sz = fx * uy - fy * ux;
102	  let sl = Math.hypot(sx, sy, sz) || 1;
103	  sx /= sl; sy /= sl; sz /= sl;
104	  const vx = sy * fz - sz * fy, vy = sz * fx - sx * fz, vz = sx * fy - sy * fx;
105	  out[0] = sx; out[1] = vx; out[2] = -fx; out[3] = 0;
106	  out[4] = sy; out[5] = vy; out[6] = -fy; out[7] = 0;
107	  out[8] = sz; out[9] = vz; out[10] = -fz; out[11] = 0;
108	  out[12] = -(sx * ex + sy * ey + sz * ez);
109	  out[13] = -(vx * ex + vy * ey + vz * ez);
110	  out[14] = fx * ex + fy * ey + fz * ez;
111	  out[15] = 1;
112	  return out;
113	}
114	
115	export function ortho(out: Mat4, left: number, right: number, bottom: number, top: number, near: number, far: number): Mat4 {
116	  out.fill(0);
117	  out[0] = 2 / (right - left);
118	  out[5] = 2 / (top - bottom);
119	  out[10] = -2 / (far - near);
120	  out[12] = -(right + left) / (right - left);
121	  out[13] = -(top + bottom) / (top - bottom);
122	  out[14] = -(far + near) / (far - near);
123	  out[15] = 1;
124	  return out;
125	}
126	
127	export function invert(out: Mat4, a: Mat4): Mat4 {
128	  const a00 = a[0], a01 = a[1], a02 = a[2], a03 = a[3];
129	  const a10 = a[4], a11 = a[5], a12 = a[6], a13 = a[7];
130	  const a20 = a[8], a21 = a[9], a22 = a[10], a23 = a[11];
131	  const a30 = a[12], a31 = a[13], a32 = a[14], a33 = a[15];
132	  const b00 = a00 * a11 - a01 * a10;
133	  const b01 = a00 * a12 - a02 * a10;
134	  const b02 = a00 * a13 - a03 * a10;
135	  const b03 = a01 * a12 - a02 * a11;
136	  const b04 = a01 * a13 - a03 * a11;
137	  const b05 = a02 * a13 - a03 * a12;
138	  const b06 = a20 * a31 - a21 * a30;
139	  const b07 = a20 * a32 - a22 * a30;
140	  const b08 = a20 * a33 - a23 * a30;
141	  const b09 = a21 * a32 - a22 * a31;
