272	export function disposeMesh(gl: WebGL2RenderingContext, mesh: ChunkMesh | null): void {
273	  if (!mesh) return;
274	  for (const g of [mesh.solid, mesh.translucent]) {
275	    if (!g) continue;
276	    gl.deleteVertexArray(g.vao);
277	    gl.deleteBuffer(g.vbo);
278	    gl.deleteBuffer(g.ibo);
279	  }
