1	import { ShaderProgram } from './gl.js';
2	
3	const FS_VS = `#version 300 es
4	precision highp float;
5	out vec2 vUv;
6	void main() {
7	  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
8	  vUv = p;
9	  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
10	}`;
11	
12	const EXTRACT_FS = `#version 300 es
13	precision highp float;
14	uniform sampler2D uScene;
15	uniform float uThreshold;
16	in vec2 vUv;
17	out vec4 outColor;
18	void main() {
19	  vec3 c = texture(uScene, vUv).rgb;
20	  float l = dot(c, vec3(0.2126, 0.7152, 0.0722));
21	  float k = max(0.0, l - uThreshold) / max(l, 0.0001);
22	  outColor = vec4(c * k, 1.0);
23	}`;
24	
25	const BLUR_FS = `#version 300 es
26	precision highp float;
27	uniform sampler2D uTex;
28	uniform vec2 uStep;
29	in vec2 vUv;
30	out vec4 outColor;
31	void main() {
32	  vec3 c = texture(uTex, vUv).rgb * 0.2270270270;
33	  c += texture(uTex, vUv + uStep * 1.3846153846).rgb * 0.3162162162;
34	  c += texture(uTex, vUv - uStep * 1.3846153846).rgb * 0.3162162162;
35	  c += texture(uTex, vUv + uStep * 3.2307692308).rgb * 0.0702702703;
36	  c += texture(uTex, vUv - uStep * 3.2307692308).rgb * 0.0702702703;
37	  outColor = vec4(c, 1.0);
38	}`;
39	
40	const COMPOSITE_FS = `#version 300 es
41	precision highp float;
42	uniform sampler2D uScene;
43	uniform sampler2D uBloom;
44	uniform vec2 uSunScreen;
45	uniform float uSunVisibility;
46	uniform float uBloomStrength;
47	uniform float uRayStrength;
48	uniform float uExposure;
49	uniform float uSaturation;
50	uniform float uContrast;
51	uniform float uVignette;
52	uniform float uUnderwater;
53	in vec2 vUv;
54	out vec4 outColor;
55	
56	void main() {
57	  vec3 c = texture(uScene, vUv).rgb;
58	  vec3 bloom = texture(uBloom, vUv).rgb;
59	  c += bloom * uBloomStrength;
60	
61	  if (uRayStrength > 0.0001 && uSunVisibility > 0.001) {
62	    vec2 delta = (uSunScreen - vUv) * (0.42 / 12.0);
63	    vec2 uv = vUv;
64	    vec3 rays = vec3(0.0);
65	    float weight = 1.0;
66	    for (int i = 0; i < 12; i++) {
67	      uv += delta;
68	      rays += texture(uBloom, clamp(uv, 0.0, 1.0)).rgb * weight;
69	      weight *= 0.84;
70	    }
71	    c += rays * (uRayStrength * uSunVisibility * 0.032);
72	  }
73	
74	  float lum = dot(c, vec3(0.2126, 0.7152, 0.0722));
75	  c = mix(vec3(lum), c, uSaturation);
76	  c *= uExposure;
77	  c = mix(c, c * c * (3.0 - 2.0 * c), uContrast);
78	  vec2 q = vUv - 0.5;
79	  float vig = 1.0 - dot(q, q) * uVignette;
80	  c *= vig;
81	  c = mix(c, c * vec3(0.72, 0.86, 1.05) + vec3(0.01, 0.02, 0.05), uUnderwater * 0.35);
82	  outColor = vec4(clamp(c, 0.0, 1.0), 1.0);
83	}`;
84	
85	export interface PostParams {
86	  sunScreen: [number, number];
87	  sunVisibility: number;
88	  underwater: boolean;
89	  time: number;
90	}
91	
92	export class PostFX {
93	  private gl: WebGL2RenderingContext;
94	  private vao: WebGLVertexArrayObject;
95	  private extract: ShaderProgram;
96	  private blur: ShaderProgram;
97	  private composite: ShaderProgram;
98	  private sceneFbo: WebGLFramebuffer | null = null;
99	  private sceneTex: WebGLTexture | null = null;
100	  private depthTex: WebGLTexture | null = null;
101	  private bloomA: { fbo: WebGLFramebuffer; tex: WebGLTexture } | null = null;
102	  private bloomB: { fbo: WebGLFramebuffer; tex: WebGLTexture } | null = null;
103	  private width = 0;
104	  private height = 0;
105	  private bloomW = 0;
106	  private bloomH = 0;
107	
108	  bloomEnabled = true;
109	  raysEnabled = true;
110	  bloomStrength = 0.34;
111	  rayStrength = 0.5;
112	  exposure = 1.02;
113	  saturation = 1.14;
114	  contrast = 0.16;
115	  vignette = 0.06;
116	
117	  constructor(gl: WebGL2RenderingContext) {
118	    this.gl = gl;
119	    this.extract = new ShaderProgram(gl, FS_VS, EXTRACT_FS);
120	    this.blur = new ShaderProgram(gl, FS_VS, BLUR_FS);
121	    this.composite = new ShaderProgram(gl, FS_VS, COMPOSITE_FS);
122	    this.vao = gl.createVertexArray()!;
123	  }
124	
125	  get sceneWidth(): number { return this.width; }
126	  get sceneHeight(): number { return this.height; }
127	
128	  resize(width: number, height: number): void {
129	    const w = Math.max(1, Math.floor(width));
130	    const h = Math.max(1, Math.floor(height));
131	    if (w === this.width && h === this.height) return;
132	    this.width = w;
133	    this.height = h;
134	    this.bloomW = Math.max(1, w >> 1);
135	    this.bloomH = Math.max(1, h >> 1);
136	    this.disposeTargets();
137	    const scene = this.colorTarget(w, h, this.gl.NEAREST);
138	    const depth = this.depthTarget(w, h);
139	    const fbo = this.gl.createFramebuffer()!;
140	    this.gl.bindFramebuffer(this.gl.FRAMEBUFFER, fbo);
141	    this.gl.framebufferTexture2D(this.gl.FRAMEBUFFER, this.gl.COLOR_ATTACHMENT0, this.gl.TEXTURE_2D, scene.tex, 0);
142	    this.gl.framebufferTexture2D(this.gl.FRAMEBUFFER, this.gl.DEPTH_ATTACHMENT, this.gl.TEXTURE_2D, depth, 0);
143	    this.gl.bindFramebuffer(this.gl.FRAMEBUFFER, null);
144	    this.sceneFbo = fbo;
145	    this.sceneTex = scene.tex;
146	    this.depthTex = depth;
147	    this.bloomA = this.colorTarget(this.bloomW, this.bloomH, this.gl.LINEAR);
148	    this.bloomB = this.colorTarget(this.bloomW, this.bloomH, this.gl.LINEAR);
149	  }
150	
151	  begin(): void {
152	    const gl = this.gl;
153	    gl.bindFramebuffer(gl.FRAMEBUFFER, this.sceneFbo);
154	    gl.viewport(0, 0, this.width, this.height);
155	  }
156	
157	  end(params: PostParams): void {
158	    const gl = this.gl;
159	    if (!this.sceneFbo || !this.sceneTex || !this.bloomA || !this.bloomB) return;
160	    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
161	    gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
162	    gl.disable(gl.BLEND);
163	    gl.disable(gl.DEPTH_TEST);
164	    gl.disable(gl.CULL_FACE);
165	    gl.bindVertexArray(this.vao);
166	
167	    if (this.bloomEnabled) {
168	      gl.bindFramebuffer(gl.FRAMEBUFFER, this.bloomA.fbo);
169	      gl.viewport(0, 0, this.bloomW, this.bloomH);
170	      this.extract.use();
171	      gl.activeTexture(gl.TEXTURE0);
172	      gl.bindTexture(gl.TEXTURE_2D, this.sceneTex);
173	      this.extract.i('uScene', 0);
174	      this.extract.f('uThreshold', 0.82);
175	      gl.drawArrays(gl.TRIANGLES, 0, 3);
176	
177	      gl.bindFramebuffer(gl.FRAMEBUFFER, this.bloomB.fbo);
178	      this.blur.use();
179	      gl.activeTexture(gl.TEXTURE0);
180	      gl.bindTexture(gl.TEXTURE_2D, this.bloomA.tex);
181	      this.blur.i('uTex', 0);
182	      this.blur.v2('uStep', 1 / this.bloomW, 0);
183	      gl.drawArrays(gl.TRIANGLES, 0, 3);
184	
185	      gl.bindFramebuffer(gl.FRAMEBUFFER, this.bloomA.fbo);
186	      gl.activeTexture(gl.TEXTURE0);
187	      gl.bindTexture(gl.TEXTURE_2D, this.bloomB.tex);
188	      this.blur.i('uTex', 0);
189	      this.blur.v2('uStep', 0, 1 / this.bloomH);
190	      gl.drawArrays(gl.TRIANGLES, 0, 3);
191	    }
192	
193	    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
194	    gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
195	    this.composite.use();
196	    gl.activeTexture(gl.TEXTURE0);
197	    gl.bindTexture(gl.TEXTURE_2D, this.sceneTex);
198	    this.composite.i('uScene', 0);
199	    gl.activeTexture(gl.TEXTURE1);
200	    gl.bindTexture(gl.TEXTURE_2D, this.bloomA.tex);
201	    this.composite.i('uBloom', 1);
202	    this.composite.v2('uSunScreen', params.sunScreen[0], params.sunScreen[1]);
203	    this.composite.f('uSunVisibility', this.raysEnabled ? params.sunVisibility : 0);
204	    this.composite.f('uBloomStrength', this.bloomEnabled ? this.bloomStrength : 0);
205	    this.composite.f('uRayStrength', this.raysEnabled ? this.rayStrength : 0);
206	    this.composite.f('uExposure', this.exposure);
207	    this.composite.f('uSaturation', this.saturation);
208	    this.composite.f('uContrast', this.contrast);
209	    this.composite.f('uVignette', this.vignette);
210	    this.composite.f('uUnderwater', params.underwater ? 1 : 0);
211	    gl.drawArrays(gl.TRIANGLES, 0, 3);
212	    gl.activeTexture(gl.TEXTURE0);
213	    gl.bindVertexArray(null);
214	    gl.enable(gl.DEPTH_TEST);
215	    gl.enable(gl.CULL_FACE);
216	  }
217	
218	  private colorTarget(w: number, h: number, filter: number): { fbo: WebGLFramebuffer; tex: WebGLTexture } {
219	    const gl = this.gl;
220	    const tex = gl.createTexture()!;
221	    gl.bindTexture(gl.TEXTURE_2D, tex);
222	    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
223	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, filter);
224	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter);
225	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
226	    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
227	    const fbo = gl.createFramebuffer()!;
228	    gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
229	    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
230	    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
231	    return { fbo, tex };
232	  }
233	
234	  private depthTarget(w: number, h: number): WebGLTexture {
235	    const gl = this.gl;
236	    const tex = gl.createTexture()!;
237	    gl.bindTexture(gl.TEXTURE_2D, tex);
238	    gl.texImage2D(gl.TEXTURE_2D, 0, gl.DEPTH_COMPONENT24, w, h, 0, gl.DEPTH_COMPONENT, gl.UNSIGNED_INT, null);
